428→  const rankAndPoll = async (jobId: string, resumeIds: string[]) => {
429→    const response = await fetch(
430→      `https://zkzontawprihrzpayeam.supabase.co/functions/v1/rank-resumes`,
431→      {
432→        method: "POST",
433→        headers: {
434→          "Content-Type": "application/json",
435→          Authorization: `Bearer ${(await supabase.auth.getSession()).data.session?.access_token}`,
436→        },
437→        body: JSON.stringify({ job_id: jobId, resume_ids: resumeIds }),
438→      }
439→    );
440→
441→    if (!response.ok) {
442→      const errBody = await response.json().catch(() => ({}));
443→      const err: any = new Error(errBody.error || "Ranking failed");
444→      err.status = response.status;
445→      throw err;
446→    }
447→    setRankingProgress(60);
448→
449→    for (let i = 0; i < 150; i++) {
450→      await new Promise((r) => setTimeout(r, 2000));
451→      // Stop polling if user switched to a different job
452→      if (activeJobRef.current !== jobId) return;
453→      const { data: resumeProgress } = await supabase.from("resumes").select("id, status").in("id", resumeIds);
454→      if (resumeProgress) {
455→        const done = resumeProgress.filter((r: any) => r.status === "done" || r.status === "failed").length;
456→        setScoredCount(done);
457→        const pct = resumeIds.length > 0 ? Math.round((done / resumeIds.length) * 35) : 0;
458→        setRankingProgress(Math.min(60 + pct, 95));
459→      }
460→
461→      const { data: jobData } = await supabase.from("jobs").select("status, processing_started_at").eq("id", jobId).single();
462→
463→      // Stuck-job detection: if processing for > 5 minutes
464→      if (jobData?.status === "processing" && jobData?.processing_started_at) {
465→        const elapsed = Date.now() - new Date(jobData.processing_started_at).getTime();
466→        if (elapsed > 5 * 60 * 1000) {
467→          setStuckJobDetected(true);
468→          setRanking(false);
469→          setRankingProgress(0);
470→          return;
471→        }
472→      }
473→
474→      if (jobData?.status === "completed") {
475→         const { data: allResumes } = await supabase.from("resumes").select("id, filename, file_path, candidate_name, parsed_json").eq("job_id", jobId);
476→         if (allResumes) {
477→           const allResumeIds = allResumes.map((r: any) => r.id);
478→            const { data: resultData } = await supabase
479→              .from("results")
480→              .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
481→              .in("resume_id", allResumeIds);
482→
483→            const resumeMap = new Map(allResumes.map((r: any) => [r.id, r]));
484→            const allMerged: Result[] = (resultData ?? []).map((r: any) => {
485→              const resume = resumeMap.get(r.resume_id);
486→              const parsed = resume?.parsed_json as any;
487→              return {
488→                ...r,
489→                overall_score: r.overall_score ?? 0,
490→                missing_skills: r.missing_skills ?? [],
491→                filename: resume?.filename ?? "Unknown",
492→                file_path: resume?.file_path ?? null,
493→                candidate_name: resume?.candidate_name ?? null,
494→                candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
495→                candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
496→                candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
497→                parsed_json: resume?.parsed_json ?? null,
498→              };
499→            });
500→          // Deduplicate by resume_id — keep highest score
501→          const deduped = new Map<string, Result>();
502→          for (const r of allMerged) {
503→            const existing = deduped.get(r.resume_id);
504→            if (!existing || r.overall_score > existing.overall_score) {
505→              deduped.set(r.resume_id, r);
506→            }
507→          }
508→          const merged = Array.from(deduped.values());
509→          merged.sort((a, b) => b.overall_score - a.overall_score);
510→          setResults(merged);
511→        }
512→        setStuckJobDetected(false);
513→        setRankingProgress(100);
514→        await refreshProfile();
515→        setTimeout(() => { resultsRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }); }, 200);
