const handleSaveConfig = async () => {
  if (!config) return;
  setSaving(true);
  const { id, updated_at, ...updates } = config;
  const { error } = await supabase.from("ranking_config").update(updates as any).eq("id", id);
  setSaving(false);
  if (error) toast.error(error.message);
  else { toast.success("Configuration saved"); fetchConfig(); }
};

const handleResetConfig = () => {
  if (!config) return;
  setConfig({
    ...config, model: "gpt-4o-mini", temperature: 0.2, max_resume_chars: 4000, num_interview_questions: 5,
    jd_analysis_prompt: DEFAULT_PROMPTS.jd_analysis,
    resume_parse_prompt: DEFAULT_PROMPTS.resume_parse,
    deep_scoring_prompt: DEFAULT_PROMPTS.deep_scoring,
  });
};

const updateConfig = (field: keyof RankingConfig, value: any) => {
  if (config) setConfig({ ...config, [field]: value });
};

const createVersion = async () => {
  if (!newForm.label || !newForm.prompt_text) { toast.error("Label and prompt text are required"); return; }
  const { error } = await supabase.from("prompt_versions").insert({
    prompt_type: studioType,
    label: newForm.label,
    prompt_text: newForm.prompt_text,
    model: newForm.model,
    temperature: newForm.temperature,
    notes: newForm.notes,
    created_by: user?.id,
  } as any);
  if (error) { toast.error(error.message); return; }
  toast.success("Version created");
  qc.invalidateQueries({ queryKey: ["prompt_versions", studioType] });
  setNewVersionDialog(false);
  setNewForm({ label: "", prompt_text: "", model: "gpt-4o-mini", temperature: 0.2, notes: "" });
};

const activateVersion = async (v: PromptVersion) => {
  // Deactivate all, activate selected
  await supabase.from("prompt_versions").update({ is_active: false } as any).eq("prompt_type", studioType);
  await supabase.from("prompt_versions").update({ is_active: true } as any).eq("id", v.id);

  // Also update ranking_config with this prompt
  const promptField = `${studioType}_prompt` as keyof RankingConfig;
  if (config) {
    await supabase.from("ranking_config").update({
      [promptField]: v.prompt_text,
      model: v.model,
      temperature: v.temperature,
    } as any).eq("id", config.id);
    fetchConfig();
  }
  toast.success(`"${v.label}" activated and deployed`);
  qc.invalidateQueries({ queryKey: ["prompt_versions", studioType] });
};

const testVersion = async (v: PromptVersion) => {
  const input = testInput || SAMPLE_INPUTS[studioType];
  setTestingId(v.id);
  try {
    const { data, error } = await supabase.functions.invoke("test-prompt", {
      body: { prompt_text: v.prompt_text, model: v.model, temperature: v.temperature, sample_input: input },
    });
    if (error) throw error;
    // Save test result
    await supabase.from("prompt_versions").update({ test_result_json: data } as any).eq("id", v.id);
    qc.invalidateQueries({ queryKey: ["prompt_versions", studioType] });
    toast.success(`Test complete (${data.latency_ms}ms, ${data.tokens.total_tokens} tokens)`);
  } catch (err: any) {
    toast.error("Test failed: " + err.message);
  }
  setTestingId(null);
};

const deleteVersion = async (v: PromptVersion) => {
  if (!confirm(`Delete version "${v.label}"?`)) return;
  await supabase.from("prompt_versions").delete().eq("id", v.id);
  qc.invalidateQueries({ queryKey: ["prompt_versions", studioType] });
  toast.success("Version deleted");
};

const openNewFromCurrent = () => {
  const promptField = `${studioType}_prompt` as keyof RankingConfig;
  setNewForm({
    label: `v${(versions?.length ?? 0) + 1}`,

  {/* Sample Input */}
  <Card>
    <CardHeader className="pb-2"><CardTitle className="text-sm font-medium text-muted-foreground">Test Sample Input</CardTitle></CardHeader>
    <CardContent>
      <Textarea
        value={testInput}
        onChange={(e) => setTestInput(e.target.value)}
        rows={3} className="font-mono text-xs"
        placeholder={SAMPLE_INPUTS[studioType]}
      />
    </CardContent>
  </Card>

  {/* Compare View */}
  {compareIds && compareVersions.length === 2 ? (
    <div className="grid grid-cols-2 gap-4">
      {compareVersions.map((v) => (
        <Card key={v.id}>
          <CardHeader className="pb-2">
            <div className="flex items-center justify-between">
              <CardTitle className="text-sm">{v.label}</CardTitle>
              {v.is_active && <Badge>Active</Badge>}
            </div>
            <CardDescription className="text-xs">{v.model} · temp {v.temperature}</CardDescription>
          </CardHeader>
          <CardContent className="space-y-3">
            <div>
              <Label className="text-xs text-muted-foreground">Prompt</Label>
              <pre className="text-xs bg-muted p-2 rounded max-h-40 overflow-auto whitespace-pre-wrap">{v.prompt_text}</pre>
            </div>
            {v.test_result_json && (
              <div>
                <Label className="text-xs text-muted-foreground">
                  Test Output ({v.test_result_json.latency_ms}ms · {v.test_result_json.tokens?.total_tokens} tokens)
                </Label>
                <pre className="text-xs bg-muted p-2 rounded max-h-60 overflow-auto whitespace-pre-wrap">{v.test_result_json.output}</pre>
              </div>
            )}
          </CardContent>
        </Card>
      ))}
    </div>
  ) : (
    /* Version List */
    <div className="space-y-3">
      {versionsLoading ? (
        <p className="text-sm text-muted-foreground">Loading versions…</p>
      ) : versions?.length === 0 ? (
        <Card><CardContent className="py-8 text-center text-muted-foreground text-sm">No versions yet. Click "New Version" to create one from the current live prompt.</CardContent></Card>
      ) : versions?.map((v) => (
        <Card key={v.id} className={v.is_active ? "border-primary/50" : ""}>
          <CardContent className="p-4">
            <div className="flex items-start justify-between gap-4">
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 mb-1">
                  <span className="font-medium text-sm">{v.label}</span>
                  {v.is_active && <Badge variant="default" className="text-xs">Active</Badge>}
                  <span className="text-xs text-muted-foreground">{v.model} · temp {v.temperature}</span>
                  <span className="text-xs text-muted-foreground">{new Date(v.created_at).toLocaleDateString()}</span>
                </div>
                {v.notes && <p className="text-xs text-muted-foreground mb-2">{v.notes}</p>}
                <pre className="text-xs bg-muted p-2 rounded max-h-24 overflow-auto whitespace-pre-wrap">{v.prompt_text.slice(0, 300)}{v.prompt_text.length > 300 ? "…" : ""}</pre>
                {v.test_result_json && (
                  <div className="mt-2 p-2 bg-muted/50 rounded border">
                    <span className="text-xs font-medium">Last test: </span>
                    <span className="text-xs text-muted-foreground">
                      {v.test_result_json.latency_ms}ms · {v.test_result_json.tokens?.total_tokens} tokens
                    </span>
                    <pre className="text-xs mt-1 max-h-32 overflow-auto whitespace-pre-wrap">{v.test_result_json.output?.slice(0, 500)}</pre>
                  </div>
                )}
              </div>
              <div className="flex flex-col gap-1 shrink-0">
                <Button
                  variant="outline" size="sm"
                  disabled={testingId === v.id}
                  onClick={() => testVersion(v)}
                >
                  {testingId === v.id ? <Loader2 className="h-3.5 w-3.5 animate-spin mr-1" /> : <Play className="h-3.5 w-3.5 mr-1" />}
                  Test
                </Button>
                {!v.is_active && (
                  <Button variant="outline" size="sm" onClick={() => activateVersion(v)}>
                    <Star className="h-3.5 w-3.5 mr-1" />Deploy
                  </Button>
                )}
                <Button
                  variant="ghost" size="sm"
                  onClick={() => {
                    if (!compareIds) {
                      setCompareIds([v.id, ""]);
                      toast.info("Select a second version to compare");
                    } else if (compareIds[1] === "") {
                      setCompareIds([compareIds[0], v.id]);
                    }
                  }}
                >
                  <GitCompare className="h-3.5 w-3.5 mr-1" />Compare
                </Button>
                <Button variant="ghost" size="sm" onClick={() => deleteVersion(v)}>
                  <Trash2 className="h-3.5 w-3.5 text-destructive" />
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>
      ))}
    </div>
  )}
</TabsContent>

{/* ── Scoring Algorithm Tab ── */}
<TabsContent value="algorithm" className="space-y-6 max-w-3xl">
  <Card>
    <CardHeader>
      <div className="flex items-center justify-between">
        <div>
          <CardTitle className="text-lg">Scoring Algorithm</CardTitle>
          <CardDescription>Configure how dimension weights, quality gates, and scoring caps are applied.</CardDescription>

