import { useState, useEffect } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Slider } from "@/components/ui/slider";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { ScrollArea } from "@/components/ui/scroll-area";
import { toast } from "sonner";
import { Separator } from "@/components/ui/separator";
import { RotateCcw, Save, Loader2, Plus, Play, History, GitCompare, Star, Trash2, Cpu, Bot, PlusCircle, X } from "lucide-react";

const PROMPT_TYPES = [
  { key: "jd_analysis", label: "JD Analysis" },
  { key: "resume_parse", label: "Resume Parse" },
  { key: "deep_scoring", label: "Deep Scoring" },
] as const;

type PromptType = typeof PROMPT_TYPES[number]["key"];

const DEFAULT_PROMPTS: Record<PromptType, string> = {
  jd_analysis: `You are an expert recruiter. Analyze a job description and extract structured intelligence including role_type, seniority, domain, critical_must_haves, preferred_must_haves, nice_to_have, tools, evaluation_dimensions with rubrics. Return ONLY valid JSON.`,
  resume_parse: `You are an expert resume parser. Extract structured data: candidate_name, skills_with_evidence, roles_with_dates, projects, tools, education, certifications, domain_experience, leadership_signals. Return ONLY valid JSON.`,
  deep_scoring: `You are an expert recruiter performing deep candidate evaluation. Score each evaluation dimension 0-100 using the provided rubric. Return hard_fit, category_scores, strengths, gaps, interview_questions, explanation, confidence. Return ONLY valid JSON.`,
};

const SAMPLE_INPUTS: Record<PromptType, string> = {
  jd_analysis: `Senior Full-Stack Engineer - FinTech\nWe need a senior engineer with 5+ years experience in React, Node.js, and PostgreSQL. Must have experience with payment systems. Nice to have: AWS, Docker, GraphQL. Remote-friendly.`,
  resume_parse: `John Doe\nSenior Software Engineer\n5 years at TechCorp building React/Node apps.\nSkills: React, TypeScript, Node.js, PostgreSQL, AWS\nBS Computer Science, MIT 2018`,
  deep_scoring: `Evaluate this candidate against the job requirements:\nCandidate has 5 years React experience, strong Node.js, basic PostgreSQL.\nJob requires: 5+ years React, Node.js, PostgreSQL, payment systems experience.\nCandidate has no payment systems experience.`,
};

interface PromptVersion {
  id: string;
  prompt_type: string;
  label: string;
  prompt_text: string;
  model: string;
  temperature: number;
  is_active: boolean;
  test_result_json: any;
  notes: string;
  created_at: string;
}

interface RankingConfig {
  id: string;
  model: string;
  temperature: number;
  max_resume_chars: number;
  num_interview_questions: number;
  jd_analysis_prompt: string;
  resume_parse_prompt: string;
  deep_scoring_prompt: string;
  default_weight_strategy: string;
  weight_overrides_json: Record<string, number>;
  hard_fit_cap: number;
  min_text_length: number;
  min_word_ratio: number;
  algorithm_version: number;
  updated_at: string;
}

const AIPromptsTab = () => {
  const { user } = useAuth();
  const qc = useQueryClient();
  const [config, setConfig] = useState<RankingConfig | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [activeTab, setActiveTab] = useState<"config" | "studio" | "algorithm">("config");
  const [studioType, setStudioType] = useState<PromptType>("jd_analysis");
  const [showHistory, setShowHistory] = useState(false);
  const [compareIds, setCompareIds] = useState<[string, string] | null>(null);
  const [testInput, setTestInput] = useState("");
  const [testingId, setTestingId] = useState<string | null>(null);
  const [newVersionDialog, setNewVersionDialog] = useState(false);
  const [newForm, setNewForm] = useState({ label: "", prompt_text: "", model: "gpt-4o-mini", temperature: 0.2, notes: "" });

  useEffect(() => { fetchConfig(); }, []);

  const fetchConfig = async () => {
    const { data, error } = await supabase
      .from("ranking_config")
      .select("*")
      .limit(1).single();
    if (error) toast.error("Error loading config: " + error.message);
    else setConfig(data as unknown as RankingConfig);
    setLoading(false);
  };

  const { data: versions, isLoading: versionsLoading } = useQuery({
    queryKey: ["prompt_versions", studioType],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("prompt_versions")
        .select("*")
        .eq("prompt_type", studioType)
        .order("created_at", { ascending: false });
      if (error) throw error;
      return data as PromptVersion[];
    },
  });

  const handleSaveConfig = async () => {
    if (!config) return;
    setSaving(true);
    const { id, updated_at, ...updates } = config;
    const { error } = await supabase.from("ranking_config").update(updates as any).eq("id", id);
    setSaving(false);
    if (error) toast.error(error.message);
    else { toast.success("Configuration saved"); fetchConfig(); }
  };

  const handleResetConfig = () => {
    if (!config) return;
    setConfig({
      ...config, model: "gpt-4o-mini", temperature: 0.2, max_resume_chars: 4000, num_interview_questions: 5,
      jd_analysis_prompt: DEFAULT_PROMPTS.jd_analysis,
      resume_parse_prompt: DEFAULT_PROMPTS.resume_parse,
      deep_scoring_prompt: DEFAULT_PROMPTS.deep_scoring,
    });
  };

  const updateConfig = (field: keyof RankingConfig, value: any) => {
    if (config) setConfig({ ...config, [field]: value });
  };

  const createVersion = async () => {
    if (!newForm.label || !newForm.prompt_text) { toast.error("Label and prompt text are required"); return; }
    const { error } = await supabase.from("prompt_versions").insert({
      prompt_type: studioType,
      label: newForm.label,
      prompt_text: newForm.prompt_text,
      model: newForm.model,
      temperature: newForm.temperature,
      notes: newForm.notes,
      created_by: user?.id,
    } as any);
    if (error) { toast.error(error.message); return; }
    toast.success("Version created");
    qc.invalidateQueries({ queryKey: ["prompt_versions", studioType] });
    setNewVersionDialog(false);
    setNewForm({ label: "", prompt_text: "", model: "gpt-4o-mini", temperature: 0.2, notes: "" });
  };

  const activateVersion = async (v: PromptVersion) => {
    // Deactivate all, activate selected
    await supabase.from("prompt_versions").update({ is_active: false } as any).eq("prompt_type", studioType);
    await supabase.from("prompt_versions").update({ is_active: true } as any).eq("id", v.id);

    // Also update ranking_config with this prompt
    const promptField = `${studioType}_prompt` as keyof RankingConfig;
    if (config) {
      await supabase.from("ranking_config").update({
        [promptField]: v.prompt_text,
        model: v.model,
        temperature: v.temperature,
      } as any).eq("id", config.id);
      fetchConfig();
    }
    toast.success(`"${v.label}" activated and deployed`);
    qc.invalidateQueries({ queryKey: ["prompt_versions", studioType] });
  };

  const testVersion = async (v: PromptVersion) => {
    const input = testInput || SAMPLE_INPUTS[studioType];
    setTestingId(v.id);
    try {
      const { data, error } = await supabase.functions.invoke("test-prompt", {
        body: { prompt_text: v.prompt_text, model: v.model, temperature: v.temperature, sample_input: input },
      });
      if (error) throw error;
      // Save test result
      await supabase.from("prompt_versions").update({ test_result_json: data } as any).eq("id", v.id);
      qc.invalidateQueries({ queryKey: ["prompt_versions", studioType] });
      toast.success(`Test complete (${data.latency_ms}ms, ${data.tokens.total_tokens} tokens)`);
    } catch (err: any) {
      toast.error("Test failed: " + err.message);
    }
    setTestingId(null);
  };

  const deleteVersion = async (v: PromptVersion) => {
    if (!confirm(`Delete version "${v.label}"?`)) return;
    await supabase.from("prompt_versions").delete().eq("id", v.id);
    qc.invalidateQueries({ queryKey: ["prompt_versions", studioType] });
    toast.success("Version deleted");
  };

  const openNewFromCurrent = () => {
    const promptField = `${studioType}_prompt` as keyof RankingConfig;
    setNewForm({
      label: `v${(versions?.length ?? 0) + 1}`,
      prompt_text: (config?.[promptField] as string) || DEFAULT_PROMPTS[studioType],
      model: config?.model || "gpt-4o-mini",
      temperature: config?.temperature ?? 0.2,
      notes: "",
    });
    setNewVersionDialog(true);
  };

  const compareVersions = versions?.filter((v) => compareIds?.includes(v.id)) ?? [];

  if (loading) return <div className="flex items-center gap-2 text-muted-foreground"><Loader2 className="h-4 w-4 animate-spin" /> Loading…</div>;
  if (!config) return <div className="text-destructive">No ranking config found.</div>;

  return (
    <div className="space-y-6">
      <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as any)}>
        <div className="flex items-center justify-between">
          <TabsList>
            <TabsTrigger value="config">Live Configuration</TabsTrigger>
            <TabsTrigger value="studio">Prompt Studio</TabsTrigger>
            <TabsTrigger value="algorithm">Scoring Algorithm</TabsTrigger>
          </TabsList>
          {activeTab === "config" && (
            <div className="flex gap-2">
              <Button variant="outline" size="sm" onClick={handleResetConfig}><RotateCcw className="h-4 w-4 mr-1" />Reset</Button>
              <Button size="sm" onClick={handleSaveConfig} disabled={saving}>
                {saving ? <Loader2 className="h-4 w-4 animate-spin mr-1" /> : <Save className="h-4 w-4 mr-1" />}Save
              </Button>
            </div>
          )}
        </div>

        {/* ── Live Configuration Tab ── */}
        <TabsContent value="config" className="space-y-6 max-w-3xl">
          <Card>
            <CardHeader><CardTitle className="text-lg">Model Settings</CardTitle></CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label>Model</Label>
                  <Select value={config.model} onValueChange={(v) => updateConfig("model", v)}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="gpt-4o-mini">gpt-4o-mini</SelectItem>
                      <SelectItem value="gpt-4o">gpt-4o</SelectItem>
                      <SelectItem value="gpt-4-turbo">gpt-4-turbo</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label>Interview Questions</Label>
                  <Input type="number" min={1} max={20} value={config.num_interview_questions} onChange={(e) => updateConfig("num_interview_questions", parseInt(e.target.value) || 5)} />
                </div>
              </div>
              <div className="space-y-2">
                <div className="flex justify-between"><Label>Temperature</Label><span className="text-sm text-muted-foreground">{config.temperature}</span></div>
                <Slider value={[config.temperature]} onValueChange={([v]) => updateConfig("temperature", Math.round(v * 100) / 100)} min={0} max={1} step={0.05} />
              </div>
              <div className="space-y-2">
                <Label>Max Resume Characters</Label>
                <Input type="number" min={1000} max={16000} step={500} value={config.max_resume_chars} onChange={(e) => updateConfig("max_resume_chars", parseInt(e.target.value) || 4000)} />
              </div>
            </CardContent>
          </Card>

          {PROMPT_TYPES.map(({ key, label }) => (
            <Card key={key}>
              <CardHeader>
                <CardTitle className="text-lg">{label} Prompt</CardTitle>
              </CardHeader>
              <CardContent>
                <Textarea
                  value={(config as any)[`${key}_prompt`] || ""}
                  onChange={(e) => updateConfig(`${key}_prompt` as any, e.target.value)}
                  rows={6} className="font-mono text-xs"
                />
              </CardContent>
            </Card>
          ))}
        </TabsContent>

        {/* ── Prompt Studio Tab ── */}
        <TabsContent value="studio" className="space-y-6">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Label className="text-sm font-medium">Prompt Type:</Label>
              <Select value={studioType} onValueChange={(v) => { setStudioType(v as PromptType); setCompareIds(null); }}>
                <SelectTrigger className="w-[180px]"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {PROMPT_TYPES.map(({ key, label }) => <SelectItem key={key} value={key}>{label}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div className="flex gap-2">
              {compareIds ? (
                <Button variant="outline" size="sm" onClick={() => setCompareIds(null)}>Exit Compare</Button>
              ) : null}
              <Button size="sm" onClick={openNewFromCurrent}><Plus className="h-4 w-4 mr-1" />New Version</Button>
            </div>
          </div>

          {/* Sample Input */}
          <Card>
            <CardHeader className="pb-2"><CardTitle className="text-sm font-medium text-muted-foreground">Test Sample Input</CardTitle></CardHeader>
            <CardContent>
              <Textarea
                value={testInput}
                onChange={(e) => setTestInput(e.target.value)}
                rows={3} className="font-mono text-xs"
                placeholder={SAMPLE_INPUTS[studioType]}
              />
            </CardContent>
          </Card>

          {/* Compare View */}
          {compareIds && compareVersions.length === 2 ? (
            <div className="grid grid-cols-2 gap-4">
              {compareVersions.map((v) => (
                <Card key={v.id}>
                  <CardHeader className="pb-2">
                    <div className="flex items-center justify-between">
                      <CardTitle className="text-sm">{v.label}</CardTitle>
                      {v.is_active && <Badge>Active</Badge>}
                    </div>
                    <CardDescription className="text-xs">{v.model} · temp {v.temperature}</CardDescription>
                  </CardHeader>
                  <CardContent className="space-y-3">
                    <div>
                      <Label className="text-xs text-muted-foreground">Prompt</Label>
                      <pre className="text-xs bg-muted p-2 rounded max-h-40 overflow-auto whitespace-pre-wrap">{v.prompt_text}</pre>
                    </div>
                    {v.test_result_json && (
                      <div>
                        <Label className="text-xs text-muted-foreground">
                          Test Output ({v.test_result_json.latency_ms}ms · {v.test_result_json.tokens?.total_tokens} tokens)
                        </Label>
                        <pre className="text-xs bg-muted p-2 rounded max-h-60 overflow-auto whitespace-pre-wrap">{v.test_result_json.output}</pre>
                      </div>
                    )}
                  </CardContent>
                </Card>
              ))}
            </div>
          ) : (
            /* Version List */
            <div className="space-y-3">
              {versionsLoading ? (
                <p className="text-sm text-muted-foreground">Loading versions…</p>
              ) : versions?.length === 0 ? (
                <Card><CardContent className="py-8 text-center text-muted-foreground text-sm">No versions yet. Click "New Version" to create one from the current live prompt.</CardContent></Card>
              ) : versions?.map((v) => (
                <Card key={v.id} className={v.is_active ? "border-primary/50" : ""}>
                  <CardContent className="p-4">
                    <div className="flex items-start justify-between gap-4">
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                          <span className="font-medium text-sm">{v.label}</span>
                          {v.is_active && <Badge variant="default" className="text-xs">Active</Badge>}
                          <span className="text-xs text-muted-foreground">{v.model} · temp {v.temperature}</span>
                          <span className="text-xs text-muted-foreground">{new Date(v.created_at).toLocaleDateString()}</span>
                        </div>
                        {v.notes && <p className="text-xs text-muted-foreground mb-2">{v.notes}</p>}
                        <pre className="text-xs bg-muted p-2 rounded max-h-24 overflow-auto whitespace-pre-wrap">{v.prompt_text.slice(0, 300)}{v.prompt_text.length > 300 ? "…" : ""}</pre>
                        {v.test_result_json && (
                          <div className="mt-2 p-2 bg-muted/50 rounded border">
                            <span className="text-xs font-medium">Last test: </span>
                            <span className="text-xs text-muted-foreground">
                              {v.test_result_json.latency_ms}ms · {v.test_result_json.tokens?.total_tokens} tokens
                            </span>
                            <pre className="text-xs mt-1 max-h-32 overflow-auto whitespace-pre-wrap">{v.test_result_json.output?.slice(0, 500)}</pre>
                          </div>
                        )}
                      </div>
                      <div className="flex flex-col gap-1 shrink-0">
                        <Button
                          variant="outline" size="sm"
                          disabled={testingId === v.id}
                          onClick={() => testVersion(v)}
                        >
                          {testingId === v.id ? <Loader2 className="h-3.5 w-3.5 animate-spin mr-1" /> : <Play className="h-3.5 w-3.5 mr-1" />}
                          Test
                        </Button>
                        {!v.is_active && (
                          <Button variant="outline" size="sm" onClick={() => activateVersion(v)}>
                            <Star className="h-3.5 w-3.5 mr-1" />Deploy
                          </Button>
                        )}
                        <Button
                          variant="ghost" size="sm"
                          onClick={() => {
                            if (!compareIds) {
                              setCompareIds([v.id, ""]);
                              toast.info("Select a second version to compare");
                            } else if (compareIds[1] === "") {
                              setCompareIds([compareIds[0], v.id]);
                            }
                          }}
                        >
                          <GitCompare className="h-3.5 w-3.5 mr-1" />Compare
                        </Button>
                        <Button variant="ghost" size="sm" onClick={() => deleteVersion(v)}>
                          <Trash2 className="h-3.5 w-3.5 text-destructive" />
                        </Button>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </TabsContent>

        {/* ── Scoring Algorithm Tab ── */}
        <TabsContent value="algorithm" className="space-y-6 max-w-3xl">
          <Card>
            <CardHeader>
              <div className="flex items-center justify-between">
                <div>
                  <CardTitle className="text-lg">Scoring Algorithm</CardTitle>
                  <CardDescription>Configure how dimension weights, quality gates, and scoring caps are applied.</CardDescription>
                </div>
                <Badge variant="outline" className="text-xs">v{config.algorithm_version}</Badge>
              </div>
            </CardHeader>
            <CardContent className="space-y-6">
              {/* Weight Strategy */}
              <div className="space-y-2">
                <Label>Dimension Weight Strategy</Label>
                <Select value={config.default_weight_strategy || "priority_boosted"} onValueChange={(v) => updateConfig("default_weight_strategy" as any, v)}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="equal">Equal — all dimensions weighted equally</SelectItem>
                    <SelectItem value="priority_boosted">Priority Boosted — skill/tool/experience dimensions get 2× weight</SelectItem>
                    <SelectItem value="custom">Custom — use manual weight overrides below</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              {/* Custom Weight Overrides */}
              {(config.default_weight_strategy === "custom") && (
                <div className="space-y-3 border rounded-lg p-4">
                  <Label className="text-sm font-medium">Weight Overrides</Label>
                  <p className="text-xs text-muted-foreground">Set relative weights for common evaluation dimensions. Higher = more influence on overall score.</p>
                  {["skill_relevance", "experience_depth", "domain_fit", "tool_familiarity", "seniority_match", "leadership_signals", "education_alignment"].map((dimKey) => {
                    const weight = config.weight_overrides_json?.[dimKey] ?? 1.0;
                    return (
                      <div key={dimKey} className="flex items-center gap-4">
                        <span className="text-sm w-40 capitalize">{dimKey.replace(/_/g, " ")}</span>
                        <Slider
                          value={[weight]}
                          onValueChange={([v]) => updateConfig("weight_overrides_json" as any, { ...config.weight_overrides_json, [dimKey]: Math.round(v * 10) / 10 })}
                          min={0.1} max={5.0} step={0.1} className="flex-1"
                        />
                        <span className="text-sm text-muted-foreground w-10 text-right">{weight.toFixed(1)}</span>
                      </div>
                    );
                  })}
                </div>
              )}

              {/* Scoring Caps */}
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label>Hard-Fit Cap</Label>
                  <p className="text-xs text-muted-foreground">Max score for candidates missing critical must-haves</p>
                  <Input type="number" min={0} max={100} value={config.hard_fit_cap ?? 49} onChange={(e) => updateConfig("hard_fit_cap" as any, parseInt(e.target.value) || 49)} />
                </div>
                <div className="space-y-2">
                  <Label>Algorithm Version</Label>
                  <p className="text-xs text-muted-foreground">Auto-tracks scoring config changes</p>
                  <Input type="number" min={1} value={config.algorithm_version ?? 1} onChange={(e) => updateConfig("algorithm_version" as any, parseInt(e.target.value) || 1)} />
                </div>
              </div>

              {/* Quality Gates */}
              <div className="space-y-3 border rounded-lg p-4">
                <Label className="text-sm font-medium">Quality Gates</Label>
                <p className="text-xs text-muted-foreground">Minimum thresholds for resume text to pass quality validation before scoring.</p>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label className="text-sm">Min Text Length (chars)</Label>
                    <Input type="number" min={50} max={1000} value={config.min_text_length ?? 100} onChange={(e) => updateConfig("min_text_length" as any, parseInt(e.target.value) || 100)} />
                  </div>
                  <div className="space-y-2">
