          <CardTitle className="text-lg">Scoring Mode</CardTitle>
          <CardDescription>Choose how resumes are scored after parsing.</CardDescription>
        </div>
        <Badge variant="outline" className="text-xs">v{config.algorithm_version}</Badge>
      </div>
    </CardHeader>
    <CardContent>
      <div className="grid grid-cols-2 gap-3">
        <button
          type="button"
          className={`flex items-start gap-3 p-4 rounded-lg border-2 text-left transition-colors ${
            (config as any).scoring_mode === "gpt" || !(config as any).scoring_mode
              ? "border-primary bg-primary/5" : "border-border hover:border-muted-foreground/30"
          }`}
          onClick={() => updateConfig("scoring_mode" as any, "gpt")}
        >
          <Bot className="h-5 w-5 text-primary mt-0.5 shrink-0" />
          <div>
            <p className="font-medium text-sm">GPT-4o (AI Scoring)</p>
            <p className="text-xs text-muted-foreground mt-1">AI evaluates each resume with nuanced understanding. Non-deterministic — scores may vary slightly between runs.</p>
          </div>
        </button>
        <button
          type="button"
          className={`flex items-start gap-3 p-4 rounded-lg border-2 text-left transition-colors ${
            (config as any).scoring_mode === "rule_based"
              ? "border-primary bg-primary/5" : "border-border hover:border-muted-foreground/30"
          }`}
          onClick={() => updateConfig("scoring_mode" as any, "rule_based")}
        >
          <Cpu className="h-5 w-5 text-primary mt-0.5 shrink-0" />
          <div>
            <p className="font-medium text-sm">Rule-Based (Deterministic)</p>
            <p className="text-xs text-muted-foreground mt-1">Predictable scoring using configurable rules. Same input always produces the same score.</p>
          </div>
        </button>
      </div>
    </CardContent>
  </Card>

  {/* GPT Mode Settings */}
  {((config as any).scoring_mode !== "rule_based") && (
    <Card>
      <CardHeader>
        <CardTitle className="text-lg">GPT Scoring Settings</CardTitle>
        <CardDescription>Configure how GPT-4o dimension weights are applied.</CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        <div className="space-y-2">
          <Label>Dimension Weight Strategy</Label>
          <Select value={config.default_weight_strategy || "priority_boosted"} onValueChange={(v) => updateConfig("default_weight_strategy" as any, v)}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value="equal">Equal — all dimensions weighted equally</SelectItem>
              <SelectItem value="priority_boosted">Priority Boosted — skill/tool/experience dimensions get 2× weight</SelectItem>
              <SelectItem value="custom">Custom — use manual weight overrides below</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {(config.default_weight_strategy === "custom") && (
          <div className="space-y-3 border rounded-lg p-4">
            <Label className="text-sm font-medium">Weight Overrides</Label>
            <p className="text-xs text-muted-foreground">Set relative weights for common evaluation dimensions. Higher = more influence on overall score.</p>
            {["skill_relevance", "experience_depth", "domain_fit", "tool_familiarity", "seniority_match", "leadership_signals", "education_alignment"].map((dimKey) => {
              const weight = config.weight_overrides_json?.[dimKey] ?? 1.0;
              return (
                <div key={dimKey} className="flex items-center gap-4">
                  <span className="text-sm w-40 capitalize">{dimKey.replace(/_/g, " ")}</span>
                  <Slider
                    value={[weight]}
                    onValueChange={([v]) => updateConfig("weight_overrides_json" as any, { ...config.weight_overrides_json, [dimKey]: Math.round(v * 10) / 10 })}
                    min={0.1} max={5.0} step={0.1} className="flex-1"
                  />
                  <span className="text-sm text-muted-foreground w-10 text-right">{weight.toFixed(1)}</span>
                </div>
              );
            })}
          </div>
        )}
      </CardContent>
    </Card>
  )}

  {/* Rule-Based Mode Settings */}
  {((config as any).scoring_mode === "rule_based") && (
    <>
      {/* Rule Dimension Weights */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Dimension Weights</CardTitle>
          <CardDescription>How much each scoring dimension contributes to the overall score. Must sum to 1.0.</CardDescription>
        </CardHeader>
        <CardContent className="space-y-3">
          {Object.keys(DEFAULT_RULE_WEIGHTS).map((dimKey) => {
            const weights = (config as any).rule_dimension_weights_json || DEFAULT_RULE_WEIGHTS;
            const weight = weights[dimKey] ?? DEFAULT_RULE_WEIGHTS[dimKey];
            return (
              <div key={dimKey} className="flex items-center gap-4">
                <span className="text-sm w-40">{RULE_DIMENSION_LABELS[dimKey] || dimKey}</span>
                <Slider
                  value={[weight]}
                  onValueChange={([v]) => {
                    const updated = { ...weights, [dimKey]: Math.round(v * 100) / 100 };
                    updateConfig("rule_dimension_weights_json" as any, updated);
                  }}
                  min={0} max={0.6} step={0.05} className="flex-1"
                />
                <span className="text-sm text-muted-foreground w-14 text-right">{(weight * 100).toFixed(0)}%</span>
              </div>
            );
          })}
          {(() => {
            const weights = (config as any).rule_dimension_weights_json || DEFAULT_RULE_WEIGHTS;
            const total = Object.values(weights).reduce((a: number, b: any) => a + (b as number), 0);
            const isValid = Math.abs(total - 1.0) < 0.02;
            return (
              <div className={`text-xs text-right ${isValid ? "text-muted-foreground" : "text-destructive font-medium"}`}>
                Total: {(total * 100).toFixed(0)}% {!isValid && "(should be ~100%)"}
              </div>
            );
          })()}
        </CardContent>
      </Card>

      {/* Experience Bands */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Experience Scoring Bands</CardTitle>
          <CardDescription>Map years of experience to scores. Candidates are scored based on where their total experience falls.</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-2">
            <div className="grid grid-cols-5 gap-2 text-xs font-medium text-muted-foreground px-1">
              <span>Min Years</span><span>Max Years</span><span>Score</span><span>Label</span><span></span>
            </div>
            {((config as any).experience_bands_json || DEFAULT_EXPERIENCE_BANDS).map((band: ExperienceBand, idx: number) => (
              <div key={idx} className="grid grid-cols-5 gap-2 items-center">
                <Input type="number" min={0} max={99} value={band.min_years} onChange={(e) => {
                  const bands = [...((config as any).experience_bands_json || DEFAULT_EXPERIENCE_BANDS)];
                  bands[idx] = { ...bands[idx], min_years: parseFloat(e.target.value) || 0 };
                  updateConfig("experience_bands_json" as any, bands);
                }} className="h-8 text-sm" />
                <Input type="number" min={0} max={99} value={band.max_years} onChange={(e) => {
                  const bands = [...((config as any).experience_bands_json || DEFAULT_EXPERIENCE_BANDS)];
                  bands[idx] = { ...bands[idx], max_years: parseFloat(e.target.value) || 0 };
                  updateConfig("experience_bands_json" as any, bands);
                }} className="h-8 text-sm" />
                <Input type="number" min={0} max={100} value={band.score} onChange={(e) => {
                  const bands = [...((config as any).experience_bands_json || DEFAULT_EXPERIENCE_BANDS)];
                  bands[idx] = { ...bands[idx], score: parseInt(e.target.value) || 0 };
                  updateConfig("experience_bands_json" as any, bands);
                }} className="h-8 text-sm" />
                <Input value={band.label} onChange={(e) => {
                  const bands = [...((config as any).experience_bands_json || DEFAULT_EXPERIENCE_BANDS)];
                  bands[idx] = { ...bands[idx], label: e.target.value };
                  updateConfig("experience_bands_json" as any, bands);
                }} className="h-8 text-sm" />
                <Button variant="ghost" size="sm" className="h-8 w-8 p-0" onClick={() => {
                  const bands = [...((config as any).experience_bands_json || DEFAULT_EXPERIENCE_BANDS)];
                  bands.splice(idx, 1);
                  updateConfig("experience_bands_json" as any, bands);
                }}><X className="h-3.5 w-3.5 text-muted-foreground" /></Button>
              </div>
            ))}
            <Button variant="outline" size="sm" className="mt-2" onClick={() => {
              const bands = [...((config as any).experience_bands_json || DEFAULT_EXPERIENCE_BANDS)];
              const lastMax = bands.length > 0 ? bands[bands.length - 1].max_years : 0;
              bands.push({ min_years: lastMax, max_years: lastMax + 5, score: 100, label: "Custom" });
              updateConfig("experience_bands_json" as any, bands);
            }}><PlusCircle className="h-3.5 w-3.5 mr-1" />Add Band</Button>
          </div>
        </CardContent>
      </Card>

      {/* Education Levels */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Education Level Scoring</CardTitle>
          <CardDescription>Score assigned to each education level. Aliases are keywords to match in resume text.</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-2">
            <div className="grid grid-cols-4 gap-2 text-xs font-medium text-muted-foreground px-1">
              <span>Level</span><span>Score</span><span className="col-span-2">Aliases (comma-separated)</span>
            </div>
            {((config as any).education_levels_json || DEFAULT_EDUCATION_LEVELS).map((level: EducationLevel, idx: number) => (
              <div key={idx} className="grid grid-cols-4 gap-2 items-center">
                <Input value={level.level} onChange={(e) => {
                  const levels = [...((config as any).education_levels_json || DEFAULT_EDUCATION_LEVELS)];
                  levels[idx] = { ...levels[idx], level: e.target.value };
                  updateConfig("education_levels_json" as any, levels);
                }} className="h-8 text-sm" />
                <Input type="number" min={0} max={100} value={level.score} onChange={(e) => {
                  const levels = [...((config as any).education_levels_json || DEFAULT_EDUCATION_LEVELS)];
                  levels[idx] = { ...levels[idx], score: parseInt(e.target.value) || 0 };
                  updateConfig("education_levels_json" as any, levels);
                }} className="h-8 text-sm" />
                <Input className="col-span-2 h-8 text-sm" value={level.aliases.join(", ")} onChange={(e) => {
                  const levels = [...((config as any).education_levels_json || DEFAULT_EDUCATION_LEVELS)];
                  levels[idx] = { ...levels[idx], aliases: e.target.value.split(",").map(a => a.trim()).filter(Boolean) };
                  updateConfig("education_levels_json" as any, levels);
                }} />
              </div>
            ))}
            <Button variant="outline" size="sm" className="mt-2" onClick={() => {
              const levels = [...((config as any).education_levels_json || DEFAULT_EDUCATION_LEVELS)];
              levels.push({ level: "custom", score: 50, aliases: [] });
              updateConfig("education_levels_json" as any, levels);
            }}><PlusCircle className="h-3.5 w-3.5 mr-1" />Add Level</Button>
          </div>
        </CardContent>
      </Card>

      {/* Skill Synonyms */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Skill Synonyms</CardTitle>
          <CardDescription>Custom synonym mappings for skill matching. These extend the built-in synonyms.</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-2">
            {Object.entries((config as any).skill_synonyms_json || {}).map(([canonical, syns], idx) => (
              <div key={idx} className="grid grid-cols-[1fr_2fr_auto] gap-2 items-center">
                <Input value={canonical} className="h-8 text-sm" onChange={(e) => {
                  const synonyms = { ...((config as any).skill_synonyms_json || {}) };
                  const val = synonyms[canonical];
                  delete synonyms[canonical];
                  synonyms[e.target.value] = val;
                  updateConfig("skill_synonyms_json" as any, synonyms);
                }} placeholder="Canonical term" />
                <Input value={(syns as string[]).join(", ")} className="h-8 text-sm" onChange={(e) => {
                  const synonyms = { ...((config as any).skill_synonyms_json || {}) };
                  synonyms[canonical] = e.target.value.split(",").map(s => s.trim()).filter(Boolean);
                  updateConfig("skill_synonyms_json" as any, synonyms);
                }} placeholder="Synonyms (comma-separated)" />
                <Button variant="ghost" size="sm" className="h-8 w-8 p-0" onClick={() => {
                  const synonyms = { ...((config as any).skill_synonyms_json || {}) };
                  delete synonyms[canonical];
                  updateConfig("skill_synonyms_json" as any, synonyms);
                }}><X className="h-3.5 w-3.5 text-muted-foreground" /></Button>
              </div>
            ))}
            <Button variant="outline" size="sm" className="mt-2" onClick={() => {
              const synonyms = { ...((config as any).skill_synonyms_json || {}) };
              synonyms[""] = [];
              updateConfig("skill_synonyms_json" as any, synonyms);
            }}><PlusCircle className="h-3.5 w-3.5 mr-1" />Add Synonym</Button>
          </div>
        </CardContent>
      </Card>

      {/* Must-Have Penalty */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Must-Have Penalty</CardTitle>
          <CardDescription>Score deducted for each missing critical must-have requirement.</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="flex items-center gap-4">
            <Slider
              value={[(config as any).must_have_penalty_per_missing ?? 15]}
              onValueChange={([v]) => updateConfig("must_have_penalty_per_missing" as any, v)}
              min={0} max={50} step={1} className="flex-1"
            />
            <span className="text-sm font-medium w-16 text-right">{(config as any).must_have_penalty_per_missing ?? 15} pts</span>
          </div>
        </CardContent>
      </Card>
    </>
  )}

  {/* Common Settings (both modes) */}
  <Card>
    <CardHeader>
      <CardTitle className="text-lg">Scoring Caps & Quality Gates</CardTitle>
    </CardHeader>
    <CardContent className="space-y-6">
      <div className="grid grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label>Hard-Fit Cap</Label>
          <p className="text-xs text-muted-foreground">Max score for candidates missing critical must-haves</p>
          <Input type="number" min={0} max={100} value={config.hard_fit_cap ?? 49} onChange={(e) => updateConfig("hard_fit_cap" as any, parseInt(e.target.value) || 49)} />
        </div>
        <div className="space-y-2">
          <Label>Algorithm Version</Label>
          <p className="text-xs text-muted-foreground">Auto-tracks scoring config changes</p>
          <Input type="number" min={1} value={config.algorithm_version ?? 1} onChange={(e) => updateConfig("algorithm_version" as any, parseInt(e.target.value) || 1)} />
        </div>
      </div>

      <div className="space-y-3 border rounded-lg p-4">
        <Label className="text-sm font-medium">Quality Gates</Label>
        <p className="text-xs text-muted-foreground">Minimum thresholds for resume text to pass quality validation before scoring.</p>
        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label className="text-sm">Min Text Length (chars)</Label>
            <Input type="number" min={50} max={1000} value={config.min_text_length ?? 100} onChange={(e) => updateConfig("min_text_length" as any, parseInt(e.target.value) || 100)} />
          </div>
          <div className="space-y-2">
            <Label className="text-sm">Min Word Ratio</Label>
            <div className="flex items-center gap-2">
              <Slider
                value={[config.min_word_ratio ?? 0.2]}
                onValueChange={([v]) => updateConfig("min_word_ratio" as any, Math.round(v * 100) / 100)}
                min={0.05} max={0.5} step={0.05} className="flex-1"
              />
              <span className="text-sm text-muted-foreground w-12 text-right">{((config.min_word_ratio ?? 0.2) * 100).toFixed(0)}%</span>
            </div>
          </div>
        </div>
      </div>

      <div className="flex justify-end gap-2">
        <Button size="sm" onClick={handleSaveConfig} disabled={saving}>
          {saving ? <Loader2 className="h-4 w-4 animate-spin mr-1" /> : <Save className="h-4 w-4 mr-1" />}Save Algorithm Settings
        </Button>
      </div>
    </CardContent>
  </Card>
</TabsContent>

