import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Button } from "@/components/ui/button";
import { CreditCard, ChevronLeft, ChevronRight, Download, ExternalLink } from "lucide-react";
import { exportToCSV } from "@/lib/csvExport";

const PAGE_SIZE = 20;

const PaymentsTab = () => {
  const [page, setPage] = useState(0);

  const { data: userMap } = useQuery({
    queryKey: ["admin_users"],
    queryFn: async () => {
      const { data, error } = await supabase.functions.invoke("admin-users", { method: "GET" });
      if (error) throw error;
      const map: Record<string, string> = {};
      (data as any[])?.forEach((u) => { map[u.id] = u.email; });
      return map;
    },
    staleTime: 5 * 60 * 1000,
  });

  // Fetch plan and pack names for display
  const { data: planMap } = useQuery({
    queryKey: ["admin_plans_map"],
    queryFn: async () => {
      const { data } = await supabase.from("plans").select("id, name");
      const map: Record<string, string> = {};
      data?.forEach((p: any) => { map[p.id] = p.name; });
      return map;
    },
    staleTime: 5 * 60 * 1000,
  });

  const { data: packMap } = useQuery({
    queryKey: ["admin_packs_map"],
    queryFn: async () => {
      const { data } = await supabase.from("credit_packs").select("id, name");
      const map: Record<string, string> = {};
      data?.forEach((p: any) => { map[p.id] = p.name; });
      return map;
    },
    staleTime: 5 * 60 * 1000,
  });

  const { data, isLoading } = useQuery({
    queryKey: ["admin_payments", page],
    queryFn: async () => {
      const from = page * PAGE_SIZE;
      const to = from + PAGE_SIZE - 1;
      const { data, error, count } = await supabase
        .from("payments")
        .select("*", { count: "exact" })
        .order("created_at", { ascending: false })
        .range(from, to);
      if (error) throw error;
      return { payments: data, total: count ?? 0 };
    },
  });

  const totalPages = Math.ceil((data?.total ?? 0) / PAGE_SIZE);

  const statusVariant = (status: string) => {
    switch (status) {
      case "paid": return "success" as const;
      case "created": return "warning" as const;
      case "failed": return "destructive" as const;
      default: return "secondary" as const;
    }
  };

  const statusLabel = (status: string) => {
    switch (status) {
      case "paid": return "Successful";
      case "created": return "Unpaid";
      case "failed": return "Failed";
      case "dismissed": return "Cancelled";
      default: return "Pending";
    }
  };

  const getItemName = (p: any) => {
    if (p.plan_id && planMap?.[p.plan_id]) return planMap[p.plan_id];
    if (p.pack_id && packMap?.[p.pack_id]) return packMap[p.pack_id];
    return "—";
  };

  const getDodoUrl = (p: any) => {
    if (!p.dodo_payment_id) return null;
    return `https://app.dodopayments.com/payments/${p.dodo_payment_id}`;
  };

  const handleExport = () => {
    if (!data?.payments?.length) return;
    const rows = data.payments.map((p: any) => ({
      payment_id: p.dodo_payment_id || p.id,
      user_email: userMap?.[p.user_id] || p.user_id,
      item: getItemName(p),
      amount: `${p.currency} ${(p.amount / 100).toFixed(2)}`,
      credits: p.credits_purchased,
      gateway: p.payment_gateway || "dodo",
      status: statusLabel(p.status),
      date: new Date(p.created_at).toISOString(),
    }));
    exportToCSV(rows, "payments");
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-semibold flex items-center gap-2">
          <CreditCard className="h-5 w-5 text-primary" />
          Payments
        </h2>
        <Button variant="outline" size="sm" onClick={handleExport} disabled={!data?.payments?.length}>
          <Download className="h-4 w-4 mr-1" />CSV
        </Button>
      </div>
      {isLoading ? (
        <div className="space-y-2">
          {[...Array(5)].map((_, i) => <Skeleton key={i} className="h-12 w-full" />)}
        </div>
      ) : (
        <div className="rounded-md border">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Payment ID</TableHead>
                <TableHead>User</TableHead>
                <TableHead>Item</TableHead>
                <TableHead>Amount</TableHead>
                <TableHead>Credits</TableHead>
                <TableHead>Gateway</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Date</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {data?.payments?.length === 0 && (
                <TableRow>
                  <TableCell colSpan={8} className="text-center text-muted-foreground py-8">No payments recorded yet.</TableCell>
                </TableRow>
              )}
              {data?.payments?.map((p: any) => {
                const dodoUrl = getDodoUrl(p);
                return (
                  <TableRow key={p.id}>
                    <TableCell className="font-mono text-xs">
                      <div className="flex items-center gap-1">
                        {p.dodo_payment_id || p.id?.slice(0, 12) + "…"}
                        {dodoUrl && (
                          <a href={dodoUrl} target="_blank" rel="noopener noreferrer" title="View on Dodo">
                            <ExternalLink className="h-3 w-3 text-primary" />
                          </a>
                        )}
                      </div>
                    </TableCell>
                    <TableCell className="text-sm max-w-[180px] truncate" title={userMap?.[p.user_id] || p.user_id}>
                      {userMap?.[p.user_id] || p.user_id?.slice(0, 8) + "…"}
                    </TableCell>
                    <TableCell className="text-sm">
                      {getItemName(p)}
                    </TableCell>
                    <TableCell>{p.currency} {(p.amount / 100).toFixed(2)}</TableCell>
                    <TableCell>{p.credits_purchased}</TableCell>
                    <TableCell>
                      <Badge variant="outline" className="text-[10px]">
                        {p.payment_gateway === "dodo" ? "Dodo" : p.payment_gateway || "—"}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <Badge variant={statusVariant(p.status)}>{statusLabel(p.status)}</Badge>
                    </TableCell>
                    <TableCell className="text-sm text-muted-foreground">
                      {new Date(p.created_at).toLocaleDateString("en-US", {
                        month: "short", day: "numeric", year: "numeric",
                        hour: "2-digit", minute: "2-digit",
                      })}
                    </TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
          {totalPages > 1 && (
            <div className="flex items-center justify-between px-4 py-3 border-t border-border">
              <span className="text-sm text-muted-foreground">Page {page + 1} of {totalPages}</span>
              <div className="flex items-center gap-2">
                <Button variant="outline" size="icon" className="h-7 w-7" disabled={page === 0} onClick={() => setPage(p => p - 1)}>
                  <ChevronLeft className="h-3.5 w-3.5" />
                </Button>
                <Button variant="outline" size="icon" className="h-7 w-7" disabled={page >= totalPages - 1} onClick={() => setPage(p => p + 1)}>
                  <ChevronRight className="h-3.5 w-3.5" />
                </Button>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default PaymentsTab;

