import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { ScrollText, ExternalLink } from "lucide-react";

const SubscriptionsSubTab = () => {
  const { data: userMap } = useQuery({
    queryKey: ["admin_users"],
    queryFn: async () => {
      const { data, error } = await supabase.functions.invoke("admin-users", { method: "GET" });
      if (error) throw error;
      const map: Record<string, string> = {};
      (data as any[])?.forEach((u) => { map[u.id] = u.email; });
      return map;
    },
    staleTime: 5 * 60 * 1000,
  });

  const { data: subscriptions, isLoading: subsLoading } = useQuery({
    queryKey: ["admin_active_subscriptions"],
    queryFn: async () => {
      const { data, error } = await supabase.functions.invoke("admin-users", { method: "GET" });
      if (error) throw error;
      return (data as any[])?.filter((u: any) => u.plan && u.plan !== "free") ?? [];
    },
  });

  const { data: webhooks, isLoading: whLoading } = useQuery({
    queryKey: ["admin_subscription_webhooks"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("subscription_webhooks")
        .select("*")
        .order("created_at", { ascending: false })
        .limit(50);
      if (error) throw error;
      return data;
    },
  });

  const formatDate = (d: string | null) => {
    if (!d) return "—";
    return new Date(d).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
  };

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-lg">Active Subscriptions</CardTitle>
        </CardHeader>
        <CardContent className="p-0">
          {subsLoading ? (
            <div className="p-4 space-y-2">{[...Array(3)].map((_, i) => <Skeleton key={i} className="h-10 w-full" />)}</div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>User</TableHead>
                  <TableHead>Plan</TableHead>
                  <TableHead>Monthly</TableHead>
                  <TableHead>Top-up</TableHead>
                  <TableHead>Bonus</TableHead>
                  <TableHead>Total</TableHead>
                  <TableHead>Expires</TableHead>
                  <TableHead>Dodo Sub</TableHead>
                  <TableHead>Status</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {subscriptions?.length === 0 && (
                  <TableRow><TableCell colSpan={9} className="text-center py-8 text-muted-foreground">No active subscriptions</TableCell></TableRow>
                )}
                {subscriptions?.map((u: any) => (
                  <TableRow key={u.id}>
                    <TableCell className="text-sm">{u.email}</TableCell>
                    <TableCell><Badge variant="secondary">{u.plan}</Badge></TableCell>
                    <TableCell className="text-sm">{u.subscription_credits ?? 0}</TableCell>
                    <TableCell className="text-sm">{u.topup_credits ?? 0}</TableCell>
                    <TableCell className="text-sm">{u.bonus_credits ?? 0}</TableCell>
                    <TableCell className="text-sm font-medium">{u.credits ?? 0}</TableCell>
                    <TableCell className="text-sm text-muted-foreground">{formatDate(u.subscription_ends_at)}</TableCell>
                    <TableCell className="font-mono text-[10px]">
                      {u.dodo_subscription_id ? (
                        <div className="flex items-center gap-1">
                          {u.dodo_subscription_id.slice(0, 16)}…
                          <a href={`https://app.dodopayments.com/subscriptions/${u.dodo_subscription_id}`} target="_blank" rel="noopener noreferrer">
                            <ExternalLink className="h-3 w-3 text-primary" />
                          </a>
                        </div>
                      ) : "—"}
                    </TableCell>
                    <TableCell>
                      <Badge variant="outline" className="text-emerald-600 border-emerald-300">Active</Badge>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-lg flex items-center gap-2">
            <ScrollText className="h-5 w-5 text-primary" />
            Webhook History
          </CardTitle>
        </CardHeader>
        <CardContent className="p-0">
          {whLoading ? (
            <div className="p-4 space-y-2">{[...Array(3)].map((_, i) => <Skeleton key={i} className="h-10 w-full" />)}</div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Event</TableHead>
                  <TableHead>Gateway</TableHead>
                  <TableHead>User</TableHead>
                  <TableHead>Subscription ID</TableHead>
                  <TableHead>Processed</TableHead>
                  <TableHead>Date</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {webhooks?.length === 0 && (
                  <TableRow><TableCell colSpan={6} className="text-center py-8 text-muted-foreground">No webhook events</TableCell></TableRow>
                )}
                {webhooks?.map((w: any) => (
                  <TableRow key={w.id}>
                    <TableCell><Badge variant="outline" className="text-xs">{w.event_type}</Badge></TableCell>
                    <TableCell>
                      <Badge variant="secondary" className="text-[10px]">
                        {w.gateway === "dodo" ? "Dodo" : w.gateway}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-sm">{w.user_id ? (userMap?.[w.user_id] || w.user_id.slice(0, 8) + "…") : "—"}</TableCell>
                    <TableCell className="font-mono text-xs">{w.dodo_subscription_id?.slice(0, 16) || "—"}</TableCell>
                    <TableCell>
                      {w.processed ? (
                        <Badge variant="secondary" className="text-xs">✓</Badge>
                      ) : (
                        <Badge variant="destructive" className="text-xs">Pending</Badge>
                      )}
                    </TableCell>
                    <TableCell className="text-sm text-muted-foreground">
                      {new Date(w.created_at).toLocaleDateString("en-US", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" })}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

export default SubscriptionsSubTab;

