 16→const ALLOWED_EXTENSIONS = [".pdf", ".docx"];
 17→
 18→/** Extract a usable email from various formats */
 19→function extractEmail(raw: string): string {
 20→  // Handle "Name <email@domain>" format
 21→  const match = raw.match(/<([^>]+)>/);
