 86→/**
 87→ * Verify Resend inbound webhook signature using Svix.
 88→ * Resend sends svix-id, svix-timestamp, svix-signature headers.
 89→ * Accepts secret as parameter — caller provides from DB or env var.
 90→ */
 91→function verifySvixSignature(req: Request, rawBody: string, secret: string): boolean {
 92→  const svixId = req.headers.get("svix-id");
 93→  const svixTimestamp = req.headers.get("svix-timestamp");
 94→  const svixSignature = req.headers.get("svix-signature");
 95→
 96→  if (!svixId || !svixTimestamp || !svixSignature) return false;
 97→
 98→  try {
 99→    const wh = new Webhook(secret);
100→    wh.verify(rawBody, {
101→      "svix-id": svixId,
102→      "svix-timestamp": svixTimestamp,
103→      "svix-signature": svixSignature,
104→    });
105→    return true;
106→  } catch (e) {
107→    console.error("Svix signature verification failed:", e);
108→    return false;
109→  }
110→}
