173→    status: number,
174→    logData: { sender?: string | null; recipient?: string | null; user_id?: string | null; job_id?: string | null; status: string; error_message?: string | null; attachments_count?: number; resumes_created?: number },
175→    responseBody: Record<string, unknown>
176→  ) => {
