178→      await supabase.from("email_ingest_logs").insert({
179→        sender: logData.sender || null,
180→        recipient: logData.recipient || null,
181→        user_id: logData.user_id || null,
182→        job_id: logData.job_id || null,
183→        status: logData.status,
184→        error_message: logData.error_message || null,
185→        attachments_count: logData.attachments_count || 0,
186→        resumes_created: logData.resumes_created || 0,
187→      });
188→    } catch (e) {
189→      console.error("Failed to log email ingest:", e);
190→      await logSystemError({
191→        function_name: "email-ingest",
192→        error_type: "INGEST_LOG_ERROR",
193→        severity: "warning",
194→        error_message: errorToMessage(e),
195→        error_stack: errorToStack(e),
196→        user_id: logData.user_id || null,
197→        job_id: logData.job_id || null,
198→      });
199→    }
200→    return new Response(JSON.stringify(responseBody), {
201→      status,
202→      headers: { ...corsHeaders, "Content-Type": "application/json" },
203→    });
204→  };
205→
206→  try {
207→    // Load platform config first — needed for webhook secret and settings
208→    const { data: config } = await supabase
209→      .from("platform_config")
210→      .select("email_ingestion_enabled, max_file_size_mb, max_resumes_per_job, resend_api_key, resend_inbound_webhook_secret")
211→      .limit(1)
212→      .single();
213→
214→    // --- [C1 FIX] Verify webhook signature before processing ---
215→    // Support both Svix (Resend) and HMAC verification
216→    const rawBodyText = await req.clone().text();
217→    const rawBody = new TextEncoder().encode(rawBodyText).buffer;
218→
219→    const hasSvixHeaders = req.headers.has("svix-id") && req.headers.has("svix-signature");
220→    let isValid = false;
221→
222→    if (hasSvixHeaders) {
223→      // Try DB-stored secret first, fallback to env var
224→      const svixSecret = (config as any)?.resend_inbound_webhook_secret || Deno.env.get("RESEND_INBOUND_WEBHOOK_SECRET");
225→      if (svixSecret) {
226→        isValid = verifySvixSignature(req, rawBodyText, svixSecret);
227→      }
228→    }
229→    if (!isValid) {
230→      isValid = await verifyWebhookSignature(req, rawBody);
231→    }
232→
233→    if (!isValid) {
234→      return await logAndRespond(
235→        401,
236→        { status: "rejected", error_message: "Invalid or missing webhook signature" },
237→        { error: "Unauthorized" }
238→      );
239→    }
240→
241→    // Check global email ingestion toggle
242→    if (config && !config.email_ingestion_enabled) {
243→      return await logAndRespond(403, { status: "rejected", error_message: "Email ingestion globally disabled" }, { error: "Email ingestion is globally disabled" });
244→    }
245→
246→    const maxFileSizeBytes = (config?.max_file_size_mb || 10) * 1024 * 1024;
247→    const maxResumesPerJob = config?.max_resumes_per_job || 50;
248→
249→    // Parse incoming payload — support structured JSON and multipart/form-data
250→    let sender: string | null = null;
251→    let recipient: string | null = null;
252→    const attachmentFiles: { filename: string; content: Uint8Array }[] = [];
253→
254→    const contentType = req.headers.get("content-type") || "";
255→
256→    if (contentType.includes("application/json")) {
257→      const body = await req.json();
258→
259→      // Resend inbound webhook format (email.received event)
260→      if (body.type === "email.received" && body.data?.email_id) {
261→        const resendData = body.data;
262→        sender = resendData.from ? extractEmail(resendData.from) : null;
263→
264→        if (resendData.to && Array.isArray(resendData.to) && resendData.to.length > 0) {
265→          recipient = extractEmail(resendData.to[0]);
266→        }
267→
268→        // Resend webhooks only include attachment metadata — fetch content via API
