275→        }
276→      }
277→      // Structured JSON format (e.g. FromFull/ToFull/Attachments)
278→      else if (body.FromFull || body.ToFull || body.Attachments) {
279→        sender = body.FromFull?.Email || body.From ? extractEmail(body.From) : null;
280→
281→        if (body.ToFull && Array.isArray(body.ToFull) && body.ToFull.length > 0) {
282→          recipient = body.ToFull[0].Email?.toLowerCase() || null;
283→        } else if (body.To) {
284→          recipient = extractEmail(body.To);
285→        }
286→
287→        // Attachments: array of { Name, Content (base64), ContentType, ContentLength }
288→        if (body.Attachments && Array.isArray(body.Attachments)) {
289→          let count = 0;
290→          for (const att of body.Attachments) {
291→            if (count >= MAX_ATTACHMENTS_PER_EMAIL) break;
