298→            attachmentFiles.push({ filename: att.Name, content: fileContent });
299→            count++;
300→          }
301→        }
302→      } else {
303→        // Legacy JSON format (backward compatible)
304→        sender = body.sender || null;
305→        recipient = body.recipient || null;
306→
307→        if (body.attachments && Array.isArray(body.attachments)) {
308→          let count = 0;
309→          for (const att of body.attachments) {
310→            if (count >= MAX_ATTACHMENTS_PER_EMAIL) break;
311→            if (!att.filename || !att.content) continue;
312→            // [M2 FIX] Enforce file type filter on legacy format too
313→            if (!hasAllowedExtension(att.filename)) continue;
314→            const fileContent = Uint8Array.from(atob(att.content), (c: string) => c.charCodeAt(0));
315→            // [H2 FIX] Enforce file size limit
316→            if (fileContent.byteLength > Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) continue;
317→            attachmentFiles.push({ filename: att.filename, content: fileContent });
318→            count++;
319→          }
320→        }
321→      }
322→    } else if (contentType.includes("multipart/form-data")) {
323→      // Multipart form-data format (backward compatible)
324→      const formData = await req.formData();
325→
326→      const envelope = formData.get("envelope") as string | null;
