347→
348→      // [M1 FIX] Extract attachments with capped iteration count
349→      const attachmentCount = parseInt(formData.get("attachments") as string || "0", 10);
350→      const maxIter = Math.min(Math.max(attachmentCount, 10), MAX_ATTACHMENTS_PER_EMAIL);
351→      let filesCollected = 0;
352→      for (let i = 1; i <= maxIter && filesCollected < MAX_ATTACHMENTS_PER_EMAIL; i++) {
353→        const file = formData.get(`attachment${i}`) as File | null;
354→        if (!file) continue;
