367→
368→      // Fallback: check for "attachment-info" pattern
369→      if (attachmentFiles.length === 0) {
370→        for (const [key, value] of formData.entries()) {
371→          if (filesCollected >= MAX_ATTACHMENTS_PER_EMAIL) break;
372→          if (key.startsWith("attachment") && value instanceof File) {
