import { useState } from "react";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import AppHeader from "@/components/AppHeader";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { Lightbulb, Send, Loader2, CheckCircle2, Sparkles, MessageSquare, Zap } from "lucide-react";

const CATEGORIES = [
  { value: "feature", label: "New Feature" },
  { value: "improvement", label: "Improvement" },
  { value: "integration", label: "Integration" },
  { value: "general", label: "General" },
];

const HIGHLIGHTS = [
  { icon: Sparkles, text: "Shape the product" },
  { icon: MessageSquare, text: "Every request is reviewed" },
  { icon: Zap, text: "Fast turnaround" },
];

const RequestFeature = () => {
  const { user } = useAuth();
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [category, setCategory] = useState("feature");
  const [submitting, setSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!title.trim()) {
      toast.error("Please enter a title");
      return;
    }
    if (!description.trim()) {
      toast.error("Please describe your idea");
      return;
    }

    if (!user) {
      toast.error("Please sign in to submit a feature request");
      return;
    }

    setSubmitting(true);
    try {
      const { error } = await supabase.from("feature_requests" as any).insert({
        user_id: user.id,
        title: title.trim(),
        description: description.trim(),
        category,
      });
      if (error) throw error;

      setSubmitted(true);
      setTitle("");
      setDescription("");
      setCategory("feature");
      toast.success("Feature request submitted!");
    } catch (err: any) {
      toast.error(err.message || "Failed to submit. Please try again.");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen bg-background">
      <AppHeader />
      <main className="mx-auto max-w-2xl px-4 py-10 space-y-8">
        {/* Hero */}
        <div className="text-center space-y-4">
          <div className="inline-flex items-center gap-1.5 bg-primary/10 text-primary text-xs font-semibold px-3 py-1 rounded-full">
            <Lightbulb className="h-3 w-3" />
            Feature Request
          </div>
          <h1 className="text-3xl sm:text-4xl font-bold tracking-tight">
            Help us build what matters
          </h1>
          <p className="text-muted-foreground max-w-md mx-auto">
            Your feedback shapes Rankora. Tell us what you'd like to see next.
          </p>
          <div className="flex items-center justify-center gap-6 flex-wrap pt-2">
            {HIGHLIGHTS.map(({ icon: Icon, text }) => (
              <div key={text} className="flex items-center gap-1.5 text-xs text-muted-foreground">
                <Icon className="h-3.5 w-3.5 text-primary" />
                {text}
              </div>
            ))}
          </div>
        </div>

        {/* Form Card */}
        <Card className="border shadow-sm">
          <CardContent className="pt-6">
            {submitted ? (
              <div className="text-center py-12 space-y-4">
                <div className="mx-auto w-14 h-14 rounded-full bg-green-50 dark:bg-green-950 flex items-center justify-center">
                  <CheckCircle2 className="h-7 w-7 text-green-600" />
                </div>
                <div>
                  <p className="text-lg font-semibold">Thank you!</p>
                  <p className="text-sm text-muted-foreground mt-1">
                    Your feature request has been submitted. We review every request.
                  </p>
                </div>
                <Button variant="outline" onClick={() => setSubmitted(false)}>
                  Submit another
                </Button>
              </div>
            ) : (
              <form onSubmit={handleSubmit} className="space-y-5">
                {/* Category */}
                <div className="space-y-2">
                  <Label className="text-sm font-medium">Category</Label>
                  <div className="flex flex-wrap gap-2">
                    {CATEGORIES.map((cat) => (
                      <Badge
                        key={cat.value}
                        variant={category === cat.value ? "default" : "outline"}
                        className="cursor-pointer transition-colors"
                        onClick={() => setCategory(cat.value)}
                      >
                        {cat.label}
                      </Badge>
                    ))}
                  </div>
                </div>

                {/* Title */}
                <div className="space-y-2">
                  <Label htmlFor="feature-title" className="text-sm font-medium">Title</Label>
                  <Input
                    id="feature-title"
                    placeholder="e.g., Bulk resume upload via ZIP file"
                    value={title}
                    onChange={(e) => setTitle(e.target.value)}
                    maxLength={100}
                    required
                  />
                  <p className="text-xs text-muted-foreground text-right">{title.length}/100</p>
                </div>

                {/* Description */}
                <div className="space-y-2">
                  <Label htmlFor="feature-description" className="text-sm font-medium">Description</Label>
                  <Textarea
                    id="feature-description"
                    placeholder="Describe the feature, the problem it solves, and how you'd use it..."
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                    maxLength={1000}
                    className="min-h-[140px]"
                    required
                  />
                  <p className="text-xs text-muted-foreground text-right">{description.length}/1000</p>
                </div>

                {/* Submit */}
                <Button type="submit" className="w-full gap-2" disabled={submitting || !user}>
                  {submitting ? (
                    <Loader2 className="h-4 w-4 animate-spin" />
                  ) : (
                    <Send className="h-4 w-4" />
                  )}
                  {submitting ? "Submitting..." : "Submit Feature Request"}
                </Button>

                {!user && (
                  <p className="text-xs text-center text-muted-foreground">
                    Please sign in to submit a feature request.
                  </p>
                )}
              </form>
            )}
          </CardContent>
        </Card>
      </main>
    </div>
  );
};

export default RequestFeature;

