import { useState } from "react";
import { useAuth } from "@/hooks/useAuth";
import { useNavigate } from "react-router-dom";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Zap, LogOut, Settings, ShieldCheck,
  AlertTriangle, Wallet, CalendarCheck, Lightbulb,
} from "lucide-react";
import { Link } from "react-router-dom";
import AuthDialog from "@/components/AuthDialog";

/** Get user initials from email or name */
function getInitials(email?: string | null): string {
  if (!email) return "?";
  const name = email.split("@")[0];
  const parts = name.split(/[._-]/);
  if (parts.length >= 2) {
    return (parts[0][0] + parts[1][0]).toUpperCase();
  }
  return name[0]?.toUpperCase() || "?";
}

const AppHeader = () => {
  const { user, profile, isAdmin, signOut } = useAuth();
  const [authOpen, setAuthOpen] = useState(false);
  const [authTab, setAuthTab] = useState<"signin" | "signup">("signin");
  const navigate = useNavigate();

  const openAuth = (tab: "signin" | "signup") => {
    setAuthTab(tab);
    setAuthOpen(true);
  };

  // Calculate total credits
  const subCredits = profile?.subscription_credits ?? 0;
  const topCredits = profile?.topup_credits ?? 0;
  const bonusCredits = profile?.bonus_credits ?? 0;
  const splitTotal = subCredits + topCredits + bonusCredits;
  const legacyCredits = profile?.credits ?? 0;
  const totalCredits = splitTotal > 0 ? splitTotal : legacyCredits;
  const isLowCredits = totalCredits < 3;

  const initials = getInitials(user?.email);

  return (
    <>
      <header className="border-b border-border bg-card">
        <div className="mx-auto max-w-[1200px] px-4 sm:px-6 flex items-center justify-between h-14">
          {/* Logo */}
          <Link to="/" className="flex items-center gap-2">
            <Zap className="h-5 w-5 text-primary" />
            <span className="font-semibold text-foreground tracking-tight">Rankora</span>
          </Link>

          {/* Right side */}
          <div className="flex items-center gap-2.5">
            {user ? (
              <>
                {/* Credits wallet */}
                <button
                  onClick={() => navigate("/settings")}
                  className={`group inline-flex items-center gap-2 rounded-lg px-3.5 py-2 text-xs font-medium transition-all cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-offset-2 ${
                    isLowCredits
                      ? "bg-destructive text-destructive-foreground hover:bg-destructive/90 shadow-sm focus-visible:ring-destructive animate-pulse"
                      : "bg-foreground text-background hover:bg-foreground/90 shadow-sm focus-visible:ring-foreground"
                  }`}
                >
                  <div className={`flex items-center justify-center h-6 w-6 rounded-md ${
                    isLowCredits ? "bg-white/20" : "bg-background/15"
                  }`}>
                    {isLowCredits ? (
                      <AlertTriangle className="h-3.5 w-3.5" />
                    ) : (
                      <Wallet className="h-3.5 w-3.5" />
                    )}
                  </div>
                  <span className="text-sm font-bold tabular-nums">{totalCredits}</span>
                  <span className={`text-xs font-medium ${isLowCredits ? "text-white/70" : "text-background/60"}`}>credits</span>
                </button>

                {/* User avatar dropdown */}
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <button className="h-[38px] w-[38px] rounded-lg bg-primary/10 text-primary text-sm font-semibold flex items-center justify-center border border-primary/20 hover:border-primary/40 hover:bg-primary/15 transition-all cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-primary/30 focus-visible:ring-offset-1">
                      {initials}
                    </button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end" className="w-48 mt-1.5">
                    <DropdownMenuItem onClick={() => navigate("/settings")}>
                      <Settings className="h-4 w-4 mr-2" />
                      Settings
                    </DropdownMenuItem>
                    {isAdmin && (
                      <DropdownMenuItem onClick={() => navigate("/admin")}>
                        <ShieldCheck className="h-4 w-4 mr-2" />
                        Admin
                      </DropdownMenuItem>
                    )}
                    <DropdownMenuSeparator />
                    <DropdownMenuItem onClick={() => navigate("/book-demo")}>
                      <CalendarCheck className="h-4 w-4 mr-2" />
                      Book Demo
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => navigate("/request-feature")}>
                      <Lightbulb className="h-4 w-4 mr-2" />
                      Request Feature
                    </DropdownMenuItem>
                    <DropdownMenuSeparator />
                    <DropdownMenuItem onClick={signOut}>
                      <LogOut className="h-4 w-4 mr-2" />
                      Sign out
                    </DropdownMenuItem>
                  </DropdownMenuContent>
                </DropdownMenu>
              </>
            ) : (
              <>
                <Button variant="ghost" size="sm" onClick={() => openAuth("signin")}>
                  Sign in
                </Button>
                <Button size="sm" onClick={() => openAuth("signup")}>
                  Sign up free
                </Button>
              </>
            )}
          </div>
        </div>
      </header>
      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab={authTab} />
    </>
  );
};

export default AppHeader;

